require dirname(__DIR__) . '/includes/bootstrap.php';require_admin();require_admin_permission('customers',request_is_post());$id=max(0,(int)($_GET['id']??0));$stmt=db()->prepare("SELECT * FROM portal_users WHERE id=? AND user_type='customer'");$stmt->execute([$id]);$customer=$stmt->fetch();if(!$customer){http_response_code(404);exit('Customer not found');}
if(request_is_post()){
 verify_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=substr(trim((string)($_POST['phone']??'')),0,80);$language=($_POST['language']??'de')==='en'?'en':'de';$active=isset($_POST['active'])?1:0;$password=(string)($_POST['new_password']??'');$errors=[];if($name===''||strlen($name)>150)$errors[]='Bitte einen Namen eingeben.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Bitte eine gültige E-Mail-Adresse eingeben.';if($password!==''&&strlen($password)<8)$errors[]='Das neue Passwort muss mindestens 8 Zeichen enthalten.';$check=db()->prepare('SELECT COUNT(*) FROM portal_users WHERE email=? AND id<>?');$check->execute([$email,$id]);if((int)$check->fetchColumn()>0)$errors[]='Diese E-Mail-Adresse ist bereits vergeben.';
 if($errors)flash('error',implode(' ',$errors));else{if($password!=='')db()->prepare('UPDATE portal_users SET name=?,email=?,phone=?,language=?,active=?,password_hash=? WHERE id=?')->execute([$name,$email,$phone,$language,$active,password_hash($password,PASSWORD_DEFAULT),$id]);else db()->prepare('UPDATE portal_users SET name=?,email=?,phone=?,language=?,active=? WHERE id=?')->execute([$name,$email,$phone,$language,$active,$id]);flash('success','Kundenkonto wurde gespeichert.');redirect('admin/customer.php?id='.$id);}
}
$requestStmt=db()->prepare('SELECT r.*,b.id AS booking_id,b.booking_reference FROM tour_requests r LEFT JOIN bookings b ON b.request_id=r.id WHERE r.customer_user_id=? ORDER BY r.created_at DESC');$requestStmt->execute([$id]);$requests=$requestStmt->fetchAll();$bookingStmt=db()->prepare('SELECT * FROM bookings WHERE customer_user_id=? ORDER BY created_at DESC');$bookingStmt->execute([$id]);$bookings=$bookingStmt->fetchAll();
