<div class="admin-content"><a class="back-admin" href="customers.php">← Kundenkonten</a><div class="page-heading compact"><div><p>KUNDENKONTO · <?= e(date('d.m.Y',strtotime($customer['created_at']))) ?></p><h1><?= e($customer['name']) ?></h1><span><?= e($customer['email']) ?> · <?= count($requests) ?> Anfragen · <?= count($bookings) ?> Buchungen</span></div></div><div class="detail-grid"><div><form class="editor-form" method="post"><?= csrf_field() ?><section class="admin-card form-card"><div class="card-head"><div><h2>Kontodaten</h2><p>Kontakt, Sprache und Portalzugang</p></div></div><div class="form-grid"><label>Name<input name="name" required maxlength="150" value="<?= e($customer['name']) ?>"></label><label>E-Mail<input name="email" type="email" required maxlength="190" value="<?= e($customer['email']) ?>"></label><label>Telefon / WhatsApp<input name="phone" maxlength="80" value="<?= e($customer['phone']) ?>"></label><label>Sprache<select name="language"><option value="de"<?= selected('de',$customer['language']) ?>>Deutsch</option><option value="en"<?= selected('en',$customer['language']) ?>>English</option></select></label><label>Neues Passwort<input name="new_password" type="password" minlength="8" autocomplete="new-password"><small>Leer lassen, um das bisherige Passwort zu behalten.</small></label><label class="check"><input type="checkbox" name="active" value="1"<?= $customer['active']?' checked':'' ?>> Portalzugang aktiv</label></div></section><div class="form-actions"><button class="primary-button" type="submit">Kundenkonto speichern</button></div></form>
<section class="admin-card booking-payment-card"><div class="card-head"><div><h2>Anfragen</h2><p>Mit diesem Kundenkonto verknüpft</p></div></div><?php if(!$requests):?><div class="empty small">Keine Anfragen vorhanden.</div><?php else:?><div class="admin-payment-list"><?php foreach($requests as $request):?><article><div><strong><?= e($request['booking_reference']?:$request['reference']) ?> · <?= e(strtoupper($request['request_type'])) ?></strong><small><?= e(date('d.m.Y',strtotime($request['created_at']))) ?> · <?= (int)$request['duration'] ?> Nächte</small></div><b><?= e(money_precise($request['estimate'])) ?></b><a href="<?= e($request['booking_id']?'booking.php?id='.(int)$request['booking_id']:'request.php?id='.(int)$request['id']) ?>">Öffnen →</a></article><?php endforeach;?></div><?php endif;?></section></div><aside class="detail-side"><section class="admin-card info-card"><h2>Kontoübersicht</h2><dl><dt>Status</dt><dd><?= $customer['active']?'Aktiv':'Gesperrt' ?></dd><dt>Registriert</dt><dd><?= e(date('d.m.Y H:i',strtotime($customer['created_at']))) ?></dd><dt>Letzter Login</dt><dd><?= $customer['last_login_at']?e(date('d.m.Y H:i',strtotime($customer['last_login_at']))):'Noch nie' ?></dd><dt>Anfragen</dt><dd><?= count($requests) ?></dd><dt>Buchungen</dt><dd><?= count($bookings) ?></dd></dl></section></aside></div></div>
